fn put_value(store: &ObjectStore, value: Value) -> String {
    store
        .put_canonical(&encode_value_node(&value).unwrap())
        .unwrap()
}

fn text(name: &str, value: &str) -> (Value, Value) {
    (Value::Text(name.to_owned()), Value::Text(value.to_owned()))
}

fn field<'a>(entries: &'a [(Value, Value)], name: &str) -> &'a Value {
    entries
        .iter()
        .find_map(|(key, value)| match key {
            Value::Text(key) if key == name => Some(value),
            _ => None,
        })
        .unwrap()
}

