// 使用 TypeScript 实现范畴的基本结构
// 定义对象类型
type Obj = symbol;

// 定义态射
interface Morphism<A extends Obj, B extends Obj> {
    source: A;
    target: B;
    id: symbol;  // 用于态射的唯一标识
}

// 定义范畴
class Category {
    private objects: Set<Obj>;
    private morphisms: Map<symbol, Morphism<any, any>>;
    private compositions: Map<string, symbol>;  // 存储组合关系

    constructor() {
        this.objects = new Set();
        this.morphisms = new Map();
        this.compositions = new Map();
    }

    // 添加对象
    addObject(obj: Obj): void {
        this.objects.add(obj);
        // 自动为每个对象创建恒等态射
        const idMorphism: Morphism<typeof obj, typeof obj> = {
            source: obj,
            target: obj,
            id: Symbol(`id_${obj.description}`)
        };
        this.morphisms.set(idMorphism.id, idMorphism);
    }

    // 添加态射
    addMorphism<A extends Obj, B extends Obj>(
        source: A,
        target: B,
        id: symbol
    ): void {
        if (!this.objects.has(source) || !this.objects.has(target)) {
            throw new Error("Source or target object does not exist in the category");
        }
        const morphism: Morphism<A, B> = { source, target, id };
        this.morphisms.set(id, morphism);
    }

    // 实现态射组合
    compose<A extends Obj, B extends Obj, C extends Obj>(
        f: Morphism<A, B>,
        g: Morphism<B, C>
    ): Morphism<A, C> {
        if (f.target !== g.source) {
            throw new Error("Morphisms cannot be composed: target and source do not match");
        }

        const compositionKey = `${f.id.description}_${g.id.description}`;
        let composedId = this.compositions.get(compositionKey);

        if (!composedId) {
            composedId = Symbol(`${f.id.description};${g.id.description}`);
            this.compositions.set(compositionKey, composedId);
        }

        return {
            source: f.source,
            target: g.target,
            id: composedId
        };
    }

    // 验证范畴的公理
    validateCategory(): boolean {
        // 1. 检查所有对象是否都有恒等态射
        for (const obj of this.objects) {
            if (!this.hasIdentityMorphism(obj)) {
                return false;
            }
        }

        // 2. 检查组合的结合律（这里只能检查已存储的组合）
        // 实际实现中需要更复杂的逻辑来验证所有可能的组合

        return true;
    }

    private hasIdentityMorphism(obj: Obj): boolean {
        return Array.from(this.morphisms.values()).some(
            m => m.source === obj && m.target === obj
        );
    }

    // 获取态射
    getMorphism(id: symbol): Morphism<any, any> | undefined {
        return this.morphisms.get(id);
    }
}

// 使用示例
const createSetCategory = () => {
    const category = new Category();

    // 创建一些集合对象
    const A = Symbol('Set_A');
    const B = Symbol('Set_B');
    const C = Symbol('Set_C');

    category.addObject(A);
    category.addObject(B);
    category.addObject(C);

    // 添加态射（函数）
    const f = Symbol('f: A->B');
    const g = Symbol('g: B->C');

    category.addMorphism(A, B, f);
    category.addMorphism(B, C, g);

