use std::io::{BufRead, Read};

use anyhow::{bail, Context, Result};

use crate::program_module::runtime::MAX_INPUT_LINE_BYTES;

pub(super) enum InputLine {
    Request(String),
    Rejected(&'static str),
}

pub(super) fn read_bounded_line(reader: &mut impl BufRead) -> Result<Option<InputLine>> {
    let mut bytes = Vec::with_capacity(MAX_INPUT_LINE_BYTES + 1);
    let read = (&mut *reader)
        .take((MAX_INPUT_LINE_BYTES + 1) as u64)
        .read_until(b'\n', &mut bytes)
        .context("failed to read runtime request")?;
    if read == 0 {
        return Ok(None);
    }
    if bytes.len() > MAX_INPUT_LINE_BYTES {
        if !bytes.ends_with(b"\n") {
            drain_through_newline(reader)?;
        }
        return Ok(Some(InputLine::Rejected(
            "runtime request exceeds the input line byte limit",
        )));
    }
    if bytes.last() == Some(&b'\n') {
        bytes.pop();
    }
    if bytes.last() == Some(&b'\r') {
        bytes.pop();
    }
    match String::from_utf8(bytes) {
        Ok(line) => Ok(Some(InputLine::Request(line))),
        Err(_) => Ok(Some(InputLine::Rejected(
            "runtime request must be valid UTF-8",
        ))),
    }
}

fn drain_through_newline(reader: &mut impl BufRead) -> Result<()> {
    loop {
        let (consumed, found_newline) = {
            let available = reader
                .fill_buf()
                .context("failed to drain oversized runtime request")?;
            if available.is_empty() {
                return Ok(());
            }
            match available.iter().position(|byte| *byte == b'\n') {
                Some(index) => (index + 1, true),
                None => (available.len(), false),
            }
        };
        reader.consume(consumed);
        if found_newline {
            return Ok(());
        }
    }
}

pub(super) fn validate_text(label: &str, value: &str, max_bytes: usize) -> Result<()> {
    if value.is_empty() || value.trim() != value {
        bail!("{label} must be non-empty without surrounding whitespace");
    }
    if value.len() > max_bytes {
        bail!("{label} exceeds the {max_bytes}-byte limit");
    }
    if value.chars().any(char::is_control) {
        bail!("{label} must not contain control characters");
    }
    Ok(())
}

